    SCSIDiskState *s = (SCSIDiskState *)opaque;
    SCSIRequest *req, *next;

    if (s->bh) {
        qemu_unregister_block_completion(s->bh);
        s->bh = NULL;
    }

    QTAILQ_FOREACH_SAFE(req, &s->requests, next, next) {
        if (req->status == SCSI_STATUS_RETRY) {
            req->status = SCSI_STATUS_RUNNING;
            switch (req->retry_type) {
                case SCSI_RETRY_READ:
                    scsi_read_data(req);
                    break;
                case SCSI_RETRY_WRITE:
                    scsi_write_data(req);
                    break;
                case SCSI_RETRY_FLUSH:
                    scsi_emulate_command(req);
                    break;
            }
            if (req->status == SCSI_STATUS_OK) {
                scsi_req_complete(req, 0);
            }
        }
    }
