void restart_scsi_dma(void *opaque) {
    SCSIDiskState *s = (SCSIDiskState *)opaque;

    if (s->bh) {
        qemu_bh_delete(s->bh);
        s->bh = NULL;
    }

    while (!QLIST_EMPTY(&s->requests)) {
        SCSIRequest *req = QLIST_FIRST(&s->requests);
        if (req->status == SCSI_RETRY) {
            req->status = 0; // Clear retry status
            switch (req->retry_type) {
                case SCSI_RETRY_READ:
                    scsi_read_data(s, req);
                    break;
                case SCSI_RETRY_WRITE:
                    scsi_write_data(s, req);
                    break;
                case SCSI_RETRY_FLUSH:
                    scsi_emulate_command(req);
                    break;
                default:
                    break;
            }
            if (req->status == 0) {
                scsi_req_complete(req, req->status);
            }
        }
    }
}

void restart_scsi_dma(void *opaque) {
    SCSIDiskState *s = (SCSIDiskState *)opaque;

    if (s->bh) {
        qemu_bh_delete(s->bh);
        s->bh = NULL;
    }

    while (!QLIST_EMPTY(&s->reqs)) {
        SCSIRequest *req = QLIST_FIRST(&s->reqs);
        if (req->status == SCSI_RETRY) {
            req->status = 0; // Clear retry flag

            switch (req->retry_type) {
                case SCSI_RETRY_READ:
                    // Emulate read operation
                    if (scsi_read_data(s, req)) {
                        scsi_req_complete(req, 0);
                    }
                    break;
                case SCSI_RETRY_WRITE:
                    // Emulate write operation
                    if (scsi_write_data(s, req)) {
                        scsi_req_complete(req, 0);
                    }
                    break;
                case SCSI_RETRY_FLUSH:
                    // Emulate flush operation
                    scsi_flush_data(s, req);
                    scsi_req_complete(req, 0);
                    break;
                default:
                    break;
            }
        }
    }
